  {
    "id": "brand-pop",
    "code": "// Brand Pop: tap the falling products, grab the logo coins, don't tap the\n// spiky ones. Uses all four image slot shapes, so it doubles as the test game\n// for the cropper. Every image draws over a fallback shape, so the game still\n// looks right with no uploads.\nplayloop.game({\n  meta: {\n    title: \"Brand Pop\",\n    hint: \"Tap the products, grab the coins, skip the spikes\",\n    maxSeconds: 30,\n    imageSlots: [\n      { id: \"background\", label: \"Background photo\", shape: \"portrait\" },\n      { id: \"banner\", label: \"Banner across the top\", shape: \"wide\" },\n      { id: \"product\", label: \"Your product\", shape: \"square\" },\n      { id: \"logo\", label: \"Your logo on the bonus coin\", shape: \"circle\" },\n    ],\n  },\n\n  init() {\n    return { things: [], nextSpawn: 0.3, combo: 0, flash: [] };\n  },\n\n  update(s, input, ctx) {\n    const dt = ctx.dt;\n\n    s.nextSpawn -= dt;\n    if (s.nextSpawn <= 0) {\n      const roll = ctx.random();\n      const kind = roll < 0.62 ? \"product\" : roll < 0.8 ? \"coin\" : \"spike\";\n      s.things.push({ kind, x: 40 + ctx.random() * 280, y: 150, vy: 70 + ctx.random() * 50 + ctx.time * 3, size: kind === \"coin\" ? 26 : 34 });\n      s.nextSpawn = Math.max(0.35, 0.9 - ctx.time * 0.015);\n    }\n\n    for (const tap of input.taps) {\n      for (let i = s.things.length - 1; i >= 0; i--) {\n        const t = s.things[i];\n        if (Math.abs(tap.x - t.x) <= t.size + 6 && Math.abs(tap.y - t.y) <= t.size + 6) {\n          if (t.kind === \"spike\") {\n            ctx.score(-20);\n            s.combo = 0;\n            ctx.sound(\"bonk\");\n          } else {\n            s.combo = Math.min(5, s.combo + 1);\n            ctx.score((t.kind === \"coin\" ? 30 : 10) * Math.max(1, Math.floor(s.combo / 2)));\n            ctx.sound(t.kind === \"coin\" ? \"chime\" : \"pop\");\n          }\n          s.flash.push({ x: t.x, y: t.y, life: 0.3 });\n          s.things.splice(i, 1);\n          break;\n        }\n      }\n    }\n\n    for (let i = s.things.length - 1; i >= 0; i--) {\n      const t = s.things[i];\n      t.y += t.vy * dt;\n      if (t.y > 680) {\n        if (t.kind === \"product\") s.combo = 0;\n        s.things.splice(i, 1);\n      }\n    }\n    for (let i = s.flash.length - 1; i >= 0; i--) {\n      s.flash[i].life -= dt;\n      if (s.flash[i].life <= 0) s.flash.splice(i, 1);\n    }\n  },\n\n  render(s, g, ctx) {\n    g.clear(\"#3fc8ff\");\n    g.image(\"slot:background\", 0, 0, 360, 640);\n\n    g.rect(0, 0, 360, 128, { fill: \"#5b3bff\" });\n    g.text(\"Your banner here\", 180, 72, { size: 22, align: \"center\", fill: \"#ffffff\" });\n    g.image(\"slot:banner\", 0, 0, 360, 128);\n    g.rect(0, 126, 360, 4, { fill: \"#18123f\" });\n\n    for (const t of s.things) {\n      if (t.kind === \"product\") {\n        g.rect(t.x - t.size, t.y - t.size, t.size * 2, t.size * 2, { fill: \"#ffffff\", stroke: \"#18123f\", lineWidth: 3, radius: 10 });\n        g.image(\"slot:product\", t.x - t.size + 3, t.y - t.size + 3, t.size * 2 - 6, t.size * 2 - 6);\n      } else if (t.kind === \"coin\") {\n        g.circle(t.x, t.y, t.size, { fill: \"#ffdd3c\", stroke: \"#18123f\", lineWidth: 3 });\n        g.image(\"slot:logo\", t.x - t.size + 3, t.y - t.size + 3, t.size * 2 - 6, t.size * 2 - 6);\n      } else {\n        const pts = [];\n        for (let i = 0; i < 16; i++) {\n          const a = (i / 16) * Math.PI * 2;\n          const r = i % 2 ? t.size * 0.55 : t.size;\n          pts.push(t.x + Math.cos(a) * r, t.y + Math.sin(a) * r);\n        }\n        g.poly(pts, { fill: \"#ff5fa2\", stroke: \"#18123f\", lineWidth: 3 });\n      }\n    }\n    for (const f of s.flash) g.circle(f.x, f.y, 40 * (1 - f.life / 0.3) + 10, { stroke: \"#ffffff\", lineWidth: 4 });\n\n    g.rect(12, 590, 150, 38, { fill: \"#ffffff\", stroke: \"#18123f\", lineWidth: 3, radius: 12 });\n    g.text(`${ctx.currentScore}`, 26, 617, { size: 22 });\n    if (s.combo >= 2) g.text(`x${Math.floor(s.combo / 2)}`, 140, 617, { size: 18, align: \"right\", fill: \"#ff7a1a\" });\n  },\n});\n"
  },
  {
    "id": "catch",
    "code": "// Catch and Collect, rewritten against the PlayLoop game contract.\n// Mirrors packages/games/src/templates/catch.ts: drag the cup, catch stars\n// (10) and golden stars (30), dodge spiky balls (-15). 25 seconds.\nplayloop.game({\n  meta: {\n    title: \"Catch and Collect\",\n    hint: \"Drag or use arrow keys to move the cup\",\n    maxSeconds: 25,\n    imageSlots: [{ id: \"star\", label: \"What falls from the sky\", shape: \"circle\" }],\n  },\n\n  init(ctx) {\n    return { cupX: ctx.width / 2, targetX: ctx.width / 2, items: [], spawnIn: 0.2, wobble: 0 };\n  },\n\n  update(s, input, ctx) {\n    const dt = ctx.dt;\n    if (input.pointer.down) s.targetX = input.pointer.x;\n    if (input.keys.left) s.targetX -= 440 * dt;\n    if (input.keys.right) s.targetX += 440 * dt;\n    s.targetX = Math.max(34, Math.min(ctx.width - 34, s.targetX));\n    s.cupX += (s.targetX - s.cupX) * Math.min(1, dt * 16);\n    s.wobble = Math.max(0, s.wobble - dt);\n\n    s.spawnIn -= dt;\n    if (s.spawnIn <= 0) {\n      const r = ctx.random();\n      s.items.push({\n        x: 24 + ctx.random() * (ctx.width - 48),\n        y: -24,\n        vy: (150 + ctx.random() * 70) * (1 + ctx.time / 28),\n        kind: r < 0.72 ? \"good\" : r < 0.85 ? \"gold\" : \"bad\",\n        rot: ctx.random() * 6,\n        spin: -3 + ctx.random() * 6,\n      });\n      s.spawnIn = Math.max(0.24, 0.58 - ctx.time * 0.012);\n    }\n\n    const cupY = ctx.height - 62;\n    for (let i = s.items.length - 1; i >= 0; i--) {\n      const it = s.items[i];\n      it.y += it.vy * dt;\n      it.rot += it.spin * dt;\n      if (it.y > cupY - 26 && it.y < cupY + 6 && Math.abs(it.x - s.cupX) < 42) {\n        if (it.kind === \"bad\") {\n          ctx.score(-15);\n          s.wobble = 0.35;\n          ctx.sound(\"bonk\");\n        } else {\n          ctx.score(it.kind === \"gold\" ? 30 : 10);\n          ctx.sound(it.kind === \"gold\" ? \"chime\" : \"pop\");\n        }\n        s.items.splice(i, 1);\n      } else if (it.y > ctx.height + 30) {\n        s.items.splice(i, 1);\n      }\n    }\n  },\n\n  render(s, g, ctx) {\n    g.clear(\"#3fc8ff\");\n    for (const it of s.items) {\n      g.save();\n      g.translate(it.x, it.y);\n      g.rotate(it.rot);\n      if (it.kind === \"bad\") {\n        const pts = [];\n        for (let i = 0; i < 20; i++) {\n          const a = (i / 20) * Math.PI * 2;\n          const r = i % 2 ? 12 : 19;\n          pts.push(Math.cos(a) * r, Math.sin(a) * r);\n        }\n        g.poly(pts, { fill: \"#ff5fa2\", stroke: \"#18123f\", lineWidth: 3 });\n      } else {\n        g.circle(0, 0, it.kind === \"gold\" ? 22 : 18, { fill: it.kind === \"gold\" ? \"#fff3a0\" : \"#ffdd3c\", stroke: \"#18123f\", lineWidth: 3 });\n        g.image(\"slot:star\", -16, -16, 32, 32);\n      }\n      g.restore();\n    }\n    const shake = s.wobble ? Math.sin(s.wobble * 60) * 5 : 0;\n    const cupY = ctx.height - 62;\n    g.rect(s.cupX - 36 + shake, cupY - 18, 72, 56, { fill: \"#ffffff\", stroke: \"#18123f\", lineWidth: 3, radius: 8 });\n  },\n});\n"
  },
  {
    "id": "desert-dash",
    "code": "// Desert Dash: a lane-free runner. Tap (or press space) to jump over\n// sandstorms, grab dates in the air. 3 lives, 60 seconds.\n// Deliberately exercises what replay has to get exactly right: gravity,\n// trigonometry, lives, and the game ending itself before the time cap.\nplayloop.game({\n  meta: {\n    title: \"Desert Dash\",\n    hint: \"Tap to jump the sandstorms, grab the dates\",\n    maxSeconds: 60,\n    lives: 3,\n    imageSlots: [{ id: \"logo\", label: \"Your logo on the bonus coin\", shape: \"circle\" }],\n  },\n\n  init(ctx) {\n    return {\n      camel: { y: 520, vy: 0, grounded: true },\n      things: [],\n      nextStorm: 1.2,\n      nextDate: 0.6,\n      speed: 210,\n      hurt: 0,\n      streak: 0,\n    };\n  },\n\n  update(s, input, ctx) {\n    const dt = ctx.dt;\n    const ground = 520;\n\n    if ((input.taps.length > 0 || input.pressed.action || input.pressed.up) && s.camel.grounded) {\n      s.camel.vy = -760;\n      s.camel.grounded = false;\n      ctx.sound(\"jump\");\n    }\n    s.camel.vy += 2100 * dt;\n    s.camel.y += s.camel.vy * dt;\n    if (s.camel.y >= ground) {\n      s.camel.y = ground;\n      s.camel.vy = 0;\n      s.camel.grounded = true;\n    }\n\n    s.speed = 210 + ctx.time * 4;\n    s.hurt = Math.max(0, s.hurt - dt);\n\n    s.nextStorm -= dt;\n    if (s.nextStorm <= 0) {\n      s.things.push({ kind: \"storm\", x: ctx.width + 30, y: ground + 8, phase: ctx.random() * Math.PI * 2 });\n      s.nextStorm = 0.9 + ctx.random() * 1.3;\n    }\n    s.nextDate -= dt;\n    if (s.nextDate <= 0) {\n      const golden = ctx.random() < 0.12;\n      s.things.push({ kind: golden ? \"coin\" : \"date\", x: ctx.width + 20, y: 330 + ctx.randomInt(0, 160), phase: 0 });\n      s.nextDate = 0.5 + ctx.random() * 0.9;\n    }\n\n    for (let i = s.things.length - 1; i >= 0; i--) {\n      const t = s.things[i];\n      t.x -= s.speed * dt;\n      if (t.kind === \"storm\") t.phase += dt * 6;\n      const bob = t.kind === \"storm\" ? Math.sin(t.phase) * 6 : 0;\n      const dx = t.x - 80;\n      const dy = t.y + bob - s.camel.y;\n      const hit = Math.hypot(dx, dy) < (t.kind === \"storm\" ? 38 : 34);\n\n      if (hit && t.kind === \"storm\" && s.hurt === 0) {\n        s.hurt = 1;\n        s.streak = 0;\n        ctx.loseLife();\n        ctx.sound(\"bonk\");\n        s.things.splice(i, 1);\n      } else if (hit && t.kind !== \"storm\") {\n        s.streak += 1;\n        const combo = Math.min(3, 1 + Math.floor(s.streak / 5));\n        ctx.score((t.kind === \"coin\" ? 30 : 10) * combo);\n        ctx.sound(\"pop\");\n        s.things.splice(i, 1);\n      } else if (t.x < -40) {\n        s.things.splice(i, 1);\n      }\n    }\n  },\n\n  render(s, g, ctx) {\n    g.clear(\"#ffdd3c\");\n    g.rect(0, 548, ctx.width, 92, { fill: \"#ff7a1a\" });\n    for (const t of s.things) {\n      if (t.kind === \"storm\") {\n        g.circle(t.x, t.y + Math.sin(t.phase) * 6, 26, { fill: \"#5e5885\", stroke: \"#18123f\", lineWidth: 3 });\n      } else if (t.kind === \"coin\") {\n        g.circle(t.x, t.y, 20, { fill: \"#fff3a0\", stroke: \"#18123f\", lineWidth: 3 });\n        g.image(\"slot:logo\", t.x - 16, t.y - 16, 32, 32);\n      } else {\n        g.ellipse(t.x, t.y, 10, 15, { fill: \"#b8652f\", stroke: \"#18123f\", lineWidth: 3 });\n      }\n    }\n    if (!(s.hurt > 0 && Math.floor(ctx.time * 12) % 2 === 0)) {\n      g.rect(56, s.camel.y - 36, 48, 44, { fill: \"#ffffff\", stroke: \"#18123f\", lineWidth: 3, radius: 10 });\n    }\n    g.text(`${ctx.currentScore}`, 20, 44, { size: 30 });\n    g.text(\"♥\".repeat(ctx.lives), ctx.width - 20, 44, { size: 26, align: \"right\", fill: \"#ff5fa2\" });\n  },\n});\n"
  }
